<script setup>
import {ref,onMounted} from 'vue'
import {api,post} from '../api'
import KnowledgeDetail from '../components/KnowledgeDetail.vue'
const emit=defineEmits(['logout'])
const tab=ref('drug'),entries=ref([]),feedback=ref([]),error=ref(''),notice=ref(''),busy=ref(false),editing=ref(false),editId=ref(null),versions=ref([]),versionEntry=ref(null),aliases=ref(''),ingredients=ref('')
const titles={drug:'药品知识',rule:'相互作用规则',food_rule:'食物饮品规则',population_rule:'特殊人群规则',feedback:'纠错反馈',ai:'AI 服务配置'}
const ruleKinds=['rule','food_rule','population_rule']
const fresh=()=>({kind:tab.value,name:'',aliases:[],ingredients:[],dosage:'',contraindications:'',precautions:'',special_population:'',food_notes:'',left:'',right:'',level:'需关注',impact:'',advice:'请咨询医生或药师，不要自行停药、换药或调整剂量。',source_name:'',source_url:'',chapter:'',source_version:'',original:''})
const form=ref(fresh()),config=ref({base_url:'',model:'',api_key:''}),hasKey=ref(false)
async function load(){error.value='';try{[entries.value,feedback.value]=await Promise.all([api('/admin/knowledge'),api('/admin/feedback')]);const c=await api('/admin/ai/config');config.value={base_url:c.base_url,model:c.model,api_key:''};hasKey.value=c.has_key}catch(e){error.value=e.message}}
function edit(entry){editId.value=entry?.id||null;form.value=entry?{...entry}:fresh();aliases.value=form.value.aliases.join('、');ingredients.value=form.value.ingredients.join('、');editing.value=true;versions.value=[];notice.value=''}
async function save(){busy.value=true;error.value='';try{form.value.aliases=aliases.value.split(/[、,，]/).map(s=>s.trim()).filter(Boolean);form.value.ingredients=ingredients.value.split(/[、,，]/).map(s=>s.trim()).filter(Boolean);await api('/admin/knowledge'+(editId.value?'/'+editId.value:''),{method:editId.value?'PUT':'POST',body:JSON.stringify(form.value)});editing.value=false;notice.value='已保存为草稿，请核对来源并审核发布。';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function change(entry,action){if(!confirm(`${action==='approve'?'审核发布':'停用'}“${entry.name}”？${action==='approve'?'发布后家庭用户可查询。':'停用后将不再参与查询和风险检查。'}`))return;busy.value=true;try{await post(`/admin/knowledge/${entry.id}/${action}`,{});notice.value='状态已更新并保存版本记录';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function history(entry){try{versions.value=await api(`/admin/knowledge/${entry.id}/versions`);versionEntry.value=entry.name;editing.value=false}catch(e){error.value=e.message}}
async function saveConfig(){busy.value=true;error.value='';try{await api('/admin/ai/config',{method:'PUT',body:JSON.stringify(config.value)});config.value.api_key='';notice.value='配置已保存到本地 backend/.env；密钥不会返回页面。';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="admin-app"><aside class="admin-sidebar"><h1>✚ 药明白</h1><p>知识库管理工作台</p><button v-for="[value,label] in Object.entries(titles)" :key="value" :class="{selected:tab===value}" @click="tab=value;editing=false;versions=[]">{{label}}</button><a href="/">打开家庭用户端 ↗</a><button @click="emit('logout')">退出管理登录</button></aside><main class="admin-main"><header><div><small>知识库管理员 · 独立管理端</small><h2>{{titles[tab]}}</h2></div><span class="tag green">仅管理公共知识</span></header><p class="subtitle">本管理端不提供家庭成员、药箱、服药记录或家庭 AI 会话的访问权限。</p><p class="error" role="alert" v-if="error">{{error}}</p><p class="feedback" role="status" v-if="notice">{{notice}}</p>
<template v-if="tab==='drug'||ruleKinds.includes(tab)"><div class="toolbar"><button class="primary" @click="edit(null)">＋ 新增{{titles[tab]}}</button><button @click="load">刷新</button></div><div class="table-scroll"><table><thead><tr><th>名称</th><th>来源／版本</th><th>审核状态</th><th>更新时间</th><th>操作</th></tr></thead><tbody><tr v-for="entry in entries.filter(e=>e.kind===tab)" :key="entry.id"><td>{{entry.name}}</td><td>{{entry.source_name}}<br>{{entry.source_version}} · 修订 {{entry.revision}}</td><td><span class="tag" :class="({draft:'orange',approved:'green',disabled:'gray'})[entry.review_status]">{{({draft:'草稿待审核',approved:'已审核发布',disabled:'已停用'})[entry.review_status]}}</span></td><td>{{entry.updated_at}}</td><td><button @click="edit(entry)">编辑</button><button :disabled="busy || entry.review_status==='approved'" @click="change(entry,'approve')">审核发布</button><button :disabled="busy || !entry.active" @click="change(entry,'disable')">停用</button><button @click="history(entry)">版本历史</button></td></tr></tbody></table></div><p class="empty" v-if="!entries.some(e=>e.kind===tab)">暂无条目，新增时必须填写来源、版本和原文依据。</p>
<section class="panel" v-if="editing"><h2>{{editId?'编辑':'新增'}}{{titles[form.kind]}}</h2><p class="subtitle">修改已发布内容会退回草稿；历史版本保留只读，重新审核后发布。</p><form @submit.prevent="save"><div class="form-grid"><label>名称 *<input v-model="form.name" required></label><template v-if="form.kind==='drug'"><label>商品名／别名（顿号分隔）<input v-model="aliases"></label><label>有效成分 *（顿号分隔）<input v-model="ingredients" required></label><label>用法说明<textarea v-model="form.dosage"></textarea></label><label>禁忌<textarea v-model="form.contraindications"></textarea></label><label>注意事项<textarea v-model="form.precautions"></textarea></label><label>特殊人群提示<textarea v-model="form.special_population"></textarea></label><label>食物／饮品注意<textarea v-model="form.food_notes"></textarea></label></template><template v-else><label>药品成分 *<input v-model="form.left" required></label><label v-if="form.kind==='population_rule'">成员角色 *
  <select v-model="form.right" required><option value="">请选择角色</option><option>成人</option><option>老人</option><option>儿童</option><option>照护者</option></select>
</label>
<label v-else>{{form.kind==='food_rule'?'食物或饮品名称':'另一药品成分'}} *<input v-model="form.right" required></label><label>风险等级<select v-model="form.level"><option>严重风险</option><option>需关注</option><option>一般提醒</option><option>数据不足</option></select></label><label>可能影响 *<textarea v-model="form.impact" required></textarea></label><label>标准建议<textarea v-model="form.advice"></textarea></label></template><label>来源名称 *<input v-model="form.source_name" required></label><label>来源 HTTPS 地址 *<input type="url" v-model="form.source_url" required></label><label>章节 *<input v-model="form.chapter" required></label><label>资料版本／日期 *<input v-model="form.source_version" required></label></div><label>原文依据 *<textarea v-model="form.original" required rows="4"></textarea></label><button class="primary" :disabled="busy">保存草稿</button><button type="button" @click="editing=false">取消</button></form></section><section class="panel" v-if="versions.length"><h2>{{versionEntry}} · 版本历史（只读）</h2><details v-for="v in versions" :key="v.id"><summary>修订 {{v.revision}} · {{v.action}} · {{v.created_at}}</summary><KnowledgeDetail :entry="v.snapshot"/></details></section></template>
<section class="panel" v-else-if="tab==='feedback'"><h2>用户知识纠错反馈</h2><p class="empty" v-if="!feedback.length">暂无反馈</p><article v-for="f in feedback" :key="f.id"><b>知识条目 #{{f.entry_id}}</b><p>{{f.message}}</p><small>{{f.created_at}}</small></article></section>
<section class="panel" v-else><h2>模型服务连接</h2><p>使用兼容 Chat Completions 的 HTTPS 服务。仅配置服务商的 API 基础地址、模型标识和密钥；例如基础地址应以 /v1 结尾，不包含 /chat/completions。</p><p class="feedback">{{hasKey?'本地已保存密钥（不回显）':'尚未保存密钥，用户端会明确提示未配置。'}}</p><form @submit.prevent="saveConfig"><label>API 基础地址<input type="url" v-model="config.base_url" placeholder="https://服务商域名/v1" required></label><label>模型名称<input v-model="config.model" required></label><label>API 密钥<input type="password" v-model="config.api_key" autocomplete="new-password" placeholder="留空保留原密钥"></label><p class="subtitle">保存于本地 backend/.env，已加入 Git 忽略。此处保存配置不会发起模型请求。</p><button class="primary" :disabled="busy">保存配置</button></form></section></main></div></template>
